<script lang="ts">
  import {formatOwnerLocalTime} from '../lib/ownerTime.ts';
  import RuntimeDiagnostics from './RuntimeDiagnostics.svelte';
  import {buildRuntimeDiagnostic} from '../lib/runtimeDiagnostics.ts';
  export let task:any=null;
  export let runtime:any=null;
  export let report:any=null;
  export let resultProjection:any=null;
  export let embedded=false;
  export let onViewWorkPackage:(id:string)=>void=()=>{};
  let resultExpanded=true;
  let copied=false;
  $: instruction=task?.instruction??{};
  $: result=resultProjection?.result??null;
  $: diagnostic=buildRuntimeDiagnostic(task,runtime);
  $: workPackageId=task?.formalWpId??task?.formal_wp_id??task?.workPackageId??instruction?.formalWpId??instruction?.workPackageId??(String(instruction?.entityType??'').toLowerCase()==='work_package'?instruction?.entityId:null);
  const value=(item:any,empty='NOT_AVAILABLE')=>item===undefined||item===null||item===''?empty:String(item);
</script>
{#if task}
<section class:embedded class="global-task-detail" data-testid="global-task-detail">
  {#if !embedded}<div class="section-label"><span>Global Task Detail</span><small>{task.taskId??task.id}</small></div>{/if}
  <div class="detail-grid"><div><span>task_id</span><b>{task.taskId??task.id}</b></div><div><span>instruction_id</span><b>{value(task.instructionId??instruction.instructionId)}</b></div><div><span>execution_id / run_id</span><b>{value(task.executionId??task.runId)}</b></div><div><span>execution status</span><b>{value(task.status??task.runtimeState??task.terminalState??task.state)}</b></div><div><span>created_at</span><b>{formatOwnerLocalTime(task.createdAt)}</b></div><div><span>started_at</span><b>{formatOwnerLocalTime(task.startedAt)}</b></div><div><span>completed_at</span><b>{formatOwnerLocalTime(task.completedAt??runtime?.completedAt)}</b></div><div><span>entity</span><b>{instruction.entityId&&instruction.entityId!=='UNBOUND'?`${instruction.entityType??'UNKNOWN'} · ${instruction.entityId}`:'GLOBAL / UNMAPPED'}</b></div><div><span>origin entity/source</span><b>{instruction.originContext?.executionContext?`${instruction.originContext.executionContext.type} · ${instruction.originContext.executionContext.id}`:value(task.origin,'UNMAPPED')}</b></div><div><span>runtime</span><b>{value(runtime?.phase??task.status??task.runtimeState)}</b></div><div><span>exit code</span><b>{value(runtime?.exitCode??task.exitCode)}</b></div></div>
  <RuntimeDiagnostics diagnostic={diagnostic} compact/>
  <section class="detail-section"><h3>Entity Binding</h3><div class="detail-grid"><div><span>Milestone</span><b>{value(task.milestoneTitle??instruction.milestoneTitle??task.milestoneId??task.milestone_id,'UNKNOWN / UNMAPPED')}</b></div><div><span>Formal Work Package</span><b>{value(workPackageId,'UNKNOWN / UNMAPPED')}</b></div><div><span>Phase</span><b>{value(task.phaseTitle??instruction.phaseTitle??task.phaseId??task.phase_id,'UNKNOWN / UNMAPPED')}</b></div><div><span>Task</span><b>{value(task.taskTitle??instruction.taskTitle??task.taskCode??instruction.taskCode)}</b></div><div><span>Origin</span><b>{value(task.origin_source??task.origin)}</b></div><div><span>Legacy Entity Reference</span><b>{value(task.legacy_entity_reference??instruction.legacyEntityReference,'NONE')}</b></div><div><span>Pull Request</span><b>{value(instruction.pullRequestId??instruction.prId,'UNKNOWN / UNMAPPED')}</b></div></div>{#if workPackageId}<button class="service-action wp-navigation" onclick={()=>onViewWorkPackage(workPackageId)}>查看 Work Package</button>{/if}</section>
  <section class="detail-section"><h3>Task Instruction · Original Instruction</h3><pre>{value(task.rawInstruction??instruction.rawInstruction??instruction.instructionBody)}</pre></section>
  <!-- Canonical Result is presented below as the Codex Result section. -->
  <section class="detail-section"><h3>Runtime</h3><div class="detail-grid"><div><span>Run ID</span><b>{value(task.runId)}</b></div><div><span>Execution ID</span><b>{value(task.executionId)}</b></div><div><span>Provider / Model</span><b>{value([runtime?.provider??task.provider,runtime?.resolvedModel??runtime?.requestedModel??task.model].filter(Boolean).join(' · '))}</b></div><div><span>Status</span><b>{value(runtime?.phase??task.status??task.runtimeState??task.terminalState??task.state)}</b></div><div><span>Branch</span><b>{value(instruction.branch??task.branch)}</b></div><div><span>Duration</span><b>{value(runtime?.duration??task.duration)}</b></div><div><span>Exit Code</span><b>{value(runtime?.exitCode??task.exitCode)}</b></div></div></section>
  <section class="detail-section"><div class="detail-heading"><h3>Codex Result</h3><div><button class="detail-action" onclick={()=>resultExpanded=!resultExpanded}>{resultExpanded?'收起':'展开'}</button><button class="detail-action" disabled={!result} onclick={async()=>{if(!result)return;await navigator.clipboard?.writeText(result.rawResult);copied=true}}>{copied?'已复制':'复制'}</button></div></div>{#if resultExpanded}{#if result}<pre>{value(result.rawResult)}</pre><p class="result-identity">{value(resultProjection?.source)} · {value(resultProjection?.resultId)} · {value(resultProjection?.resultHash)}</p>{:else}<p>NOT_AVAILABLE</p>{/if}{/if}</section>
  <section class="detail-section"><h3>Evidence</h3><p>{value(report?.runId??runtime?.runId,'暂无相关执行证据')}</p></section>
</section>
{/if}
<style>
 .global-task-detail{width:100%;min-width:0;max-width:100%;margin:12px 20px;overflow:hidden;border:1px solid var(--border);border-radius:var(--radius-md);box-sizing:border-box;background:var(--surface);padding:14px;box-shadow:var(--shadow-panel)}.global-task-detail.embedded{margin:0;padding:4px 20px 28px;border:0;border-radius:0;box-shadow:none}.global-task-detail>*{min-width:0;max-width:100%;box-sizing:border-box}.detail-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px 14px;min-width:0;max-width:100%}.embedded>.detail-grid{grid-template-columns:1fr 1fr;padding:12px 0}.embedded .detail-grid{grid-template-columns:1fr}.detail-grid div{display:grid;gap:2px;min-width:0;max-width:100%}.detail-grid span{font-size:10px;color:var(--text-3)}.detail-grid b{min-width:0;max-width:100%;overflow:hidden;font-size:11px;text-overflow:ellipsis;white-space:nowrap}.detail-section{min-width:0;max-width:100%;overflow:hidden;border-top:1px solid var(--border-soft);margin-top:12px;padding-top:10px}.detail-section h3{margin:0 0 7px;font-size:12px}.detail-section pre{min-width:0;max-width:100%;max-height:260px;margin:0;overflow-x:hidden;overflow-y:auto;box-sizing:border-box;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-word;font:11px/1.5 var(--font-tech);color:var(--text-1)}.detail-section p{min-width:0;max-width:100%;margin:0;color:var(--text-2);font-size:11px;overflow-wrap:anywhere;word-break:break-word}.detail-section .result-identity{margin-top:8px;font:9px/1.4 var(--font-tech);overflow-wrap:anywhere}.detail-heading{display:flex;min-width:0;max-width:100%;align-items:center;justify-content:space-between;gap:8px}.detail-heading h3{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.detail-heading>div{display:flex;flex:0 0 auto;gap:5px}.detail-action{margin-left:0;border:1px solid var(--border);border-radius:5px;background:var(--surface-2);color:var(--text-2);padding:4px 8px;font-size:10px;cursor:pointer}.detail-action:disabled{cursor:not-allowed;opacity:.45}.wp-navigation{margin-top:10px}
</style>
